from pathlib import Path
import html, json, shutil, subprocess, sys
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'build/pages'
OUT.mkdir(parents=True,exist_ok=True)
CSS='body{margin:0;background:#faf8f4;color:#242924;font:17px/1.65 system-ui,sans-serif}*{box-sizing:border-box}main{max-width:960px;margin:auto;padding:42px 24px 70px}h1,h2{font-family:Georgia,serif;line-height:1.15}h1{font-size:clamp(2.3rem,6vw,4rem);margin:20px 0}h2{font-size:1.7rem}a{color:#245b4b;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #a35b24;outline-offset:5px}.eyebrow{font-size:.78rem;text-transform:uppercase;letter-spacing:.12em}.lead{font-size:1.2rem;max-width:720px}.actions{display:flex;gap:16px;flex-wrap:wrap;margin:26px 0}.button{border:1px solid #245b4b;padding:12px 18px;text-decoration:none;font-weight:600}.primary{background:#245b4b;color:#fff}section{border-top:1px solid #c9cec5;padding-top:22px;margin-top:34px}details{border-top:1px solid #d6d9d1;padding:15px 0}summary{cursor:pointer;font-weight:600}details p{max-width:760px}small{color:#596259}footer{margin-top:40px;font-size:.9rem}code{overflow-wrap:anywhere}ul{padding-left:22px}@media(max-width:550px){main{padding:26px 18px}.actions{gap:10px}.button{width:100%;text-align:center}}'
def page(title,body):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+CSS+'</style></head><body><main><p class="eyebrow">Tony Wu · Practice tools</p>'+body+'<footer><a href="https://haitaowu12.github.io/tony-wu-home/">About Tony Wu</a> · <a href="deployment.json">Publication record</a></footer></main></body></html>'
subprocess.run([sys.executable,str(ROOT/'scripts/package_learning.py'),'--out',str(OUT/'personal-growth-copilot-learning.zip')],check=True)
import zipfile
with zipfile.ZipFile(OUT/'personal-growth-copilot-learning.zip') as z:
 (OUT/'requirements-writing.html').write_bytes(z.read('requirements-writing.html'))
body='<h1>Personal Growth Copilot</h1><p class="lead">Think through a situation, rehearse a conversation, or practise a skill with a portable agent skill.</p><p>One explicitly invoked skill brings together personal growth, interpersonal situations, twelve leadership methods and source-grounded learning. Session-only use is the default; optional records stay under your control.</p><div class="actions"><a class="button primary" href="requirements-writing.html">Try the requirements lesson</a><a class="button" href="personal-growth-copilot-learning.zip" download>Download the current candidate</a></div><p><small>Skill 0.5.0-alpha.1 · Requirements lesson 1.0.2 · Development candidate</small></p><section><h2>Learn through practice</h2><p>The self-contained lesson covers three concepts with twelve scenario questions, worked examples, written applications, self-review and delayed retrieval. No account or model is required. Progress saving is optional; export progress before closing if saving is off.</p><p>The archive includes the lesson and portable skill sources. Learning effectiveness and human content acceptance remain open.</p></section><section><h2>Use the conversational skill</h2><p>Install the portable skill in a compatible agent host, then invoke <code>$personal-growth-copilot</code> with the situation or skill you want to work on. It loads only the relevant reference material. Leadership and interpersonal practice are conversational; they are not additional offline courses.</p><p><a href="https://github.com/haitaowu12/personal-growth-copilot">Installation, source, privacy boundaries and current release status</a></p></section><section><h2>Scope</h2><p>This is a reflection and practice tool. It preserves agency, consent and source limits; it does not provide therapy, diagnosis or guaranteed outcomes. The development candidate is separate from the older published installation tag.</p></section>'
(OUT/'index.html').write_text(page('Personal Growth Copilot — reflection and practice',body))
